pub(super) fn finite_diff(lhs: Option<f64>, rhs: Option<f64>) -> Option<f64> {
    match (lhs, rhs) {
        (Some(lhs), Some(rhs)) if lhs.is_finite() && rhs.is_finite() => Some(lhs - rhs),
        _ => None,
    }
}

pub(super) fn format_delta(delta: Option<f64>) -> String {
    match delta {
        Some(value) => format!("{:+.6e}", value),
        None => "n/a".to_string(),
    }
}

pub(super) fn mean_std(data: &[f64]) -> Option<(f64, f64)> {
    let n = data.len();
    if n == 0 {
        return None;
    }
    let mean = data.iter().sum::<f64>() / n as f64;
    if n == 1 {
        return Some((mean, 0.0));
    }
    let var_num: f64 = data
        .iter()
        .map(|&x| {
            let dx = x - mean;
            dx * dx
        })
        .sum();
    Some((mean, (var_num / (n - 1) as f64).sqrt()))
}
